// Renderiza slides científicos via renderer service
// Input: { production_id, scenes: [{ layout, ...props }] }

const RENDERER = $env.RENDERER_URL || 'http://renderer:3000';

const body  = $input.first().json.body || $input.first().json;
const pid   = body.production_id;
const scenes = body.scenes || [];

if (!scenes.length) throw new Error('scenes[] is required');

const results = [];

for (let i = 0; i < scenes.length; i++) {
  const props = scenes[i];
  const outputName = `${pid}-slide-${i}.mp4`;

  console.log(`[${pid}] Rendering slide ${i}: ${props.layout}`);

  const r = await fetch(`${RENDERER}/render`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ props, output: outputName }),
  });

  if (!r.ok) {
    const err = await r.text();
    throw new Error(`Slide ${i} render failed: ${r.status} ${err}`);
  }

  const result = await r.json();
  console.log(`[${pid}] Slide ${i} done: ${result.path}`);
  results.push(result);
}

return [{
  json: {
    production_id: pid,
    slide_count: results.length,
    slides: results.map((r, i) => ({
      index: i,
      path: r.path,
      url:  r.url,
    })),
  }
}];
